  /// Not exactly [`room_code_length`] characters.
  const factory RoomCodeCheck.wrongLength() = RoomCodeCheck_WrongLength;

  /// A character outside [`room_code_alphabet`].
  const factory RoomCodeCheck.invalidChar({
